n&gt;&lt;span class=&quot;NormalTextRun SCXW21248068 BCX8&quot; data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;ed in New York City), and the John Adams Project&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW21248068 BCX8&quot; data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;&amp;nbsp;(centered in Washington, DC&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW21248068 BCX8&quot; data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;)&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW21248068 BCX8&quot; data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW21248068 BCX8&quot; data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span class=&quot;EOP SCXW21248068 BCX8&quot; data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:240}&quot;&gt;Special consideration will be given to applications submitted by June 19, 2026.&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;WHAT YOU&#39;LL DO&lt;/strong&gt;&amp;nbsp;&lt;/h2&gt;
