&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Supervise the&amp;nbsp;directors&amp;nbsp;of the&amp;nbsp;ACLU’s Abortion Criminal&amp;nbsp;Defense&amp;nbsp;Initiative, Capital Punishment Project, Criminal Law Reform Project, the National Prison Project, Racial Justice Program, and John Adams&amp;nbsp;Project.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Provide high-level advice and guidance on litigation strategy and legal practice issues&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Oversee and provide input into the development and implementation of the projects’ strategic plans and budgets&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Supervise the staff attorney&amp;nbsp;and other staff&amp;nbsp;assigned to the Center&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
