&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Discover Rewarding Work as a Caregiver with pay rates starting at $20 per hour and up to $25 per hour! We are currently looking for Caregivers in Ka&#39;anapali, Kahana, and Lahaina areas.&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:259}&quot;&gt;Come join BAYADA and see why we were voted Top Home Care Provider in Hawaii multiple years in a row!&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Are you looking for a&lt;/span&gt; &lt;span data-contrast=&quot;auto&quot;&gt;meaningful career, where you can make a difference in the lives of others—and yours as well?&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At BAYADA&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;,&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt; we seek people who &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;share our passion for caring and are committed to &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;helping people live their best lives at home. &lt;span class=&quot;TextRun SCXW263513314 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW263513314 BCX0&quot;&gt;As a member of our p&lt;span class=&quot;TrackChangeTextInsertion TrackedChange SCXW263513314 BCX0&quot;&gt;ersonal care and companionship team&lt;/span&gt;, you will &lt;span class=&quot;TrackChangeTextInsertion TrackedChange SCXW263513314 BCX0&quot;&gt;do truly meaningful&lt;/span&gt;&lt;span class=&quot;TrackChangeTextInsertion TrackedChange SCXW263513314 BCX0&quot;&gt; work—and &lt;/span&gt;be valued, respected, and heard. &lt;span class=&quot;TrackChangeTextInsertion TrackedChange SCXW263513314 BCX0&quot;&gt;While you &lt;/span&gt;&lt;span class=&quot;TrackChangeTextInsertion TrackedChange SCXW263513314 BCX0&quot;&gt;support&lt;/span&gt; clients &lt;span class=&quot;TrackChangeTextInsertion TrackedChange SCXW263513314 BCX0&quot;&gt;one-on-one &lt;/span&gt;with activities of daily living&lt;span class=&quot;TrackChangeTextInsertion TrackedChange SCXW263513314 BCX0&quot;&gt;, we’ll support you with t&lt;/span&gt;&lt;span class=&quot;TrackChangeTextInsertion TrackedChange SCXW263513314 BCX0&quot;&gt;raining, flexibility, and a team dedicated to &lt;/span&gt;&lt;span class=&quot;TrackChangeTextInsertion TrackedChange SCXW263513314 BCX0&quot;&gt;creating &lt;/span&gt;&lt;span class=&quot;TrackChangeTextInsertion TrackedChange SCXW263513314 BCX0&quot;&gt;a &lt;/span&gt;&lt;span class=&quot;TrackChangeTextInsertion TrackedChange SCXW263513314 BCX0&quot;&gt;great employee experience. &lt;span class=&quot;TextRun SCXW125721225 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW125721225 BCX0&quot;&gt;We are currently recruiting for a&lt;/span&gt;&lt;/span&gt; Personal Care &lt;span class=&quot;TrackChangeTextInsertion TrackedChange SCXW125721225 BCX0&quot;&gt;&lt;span class=&quot;TrackedChange SCXW125721225 BCX0&quot;&gt;&lt;span class=&quot;TextRun SCXW125721225 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW125721225 BCX0&quot;&gt;Aide&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; &lt;span class=&quot;TrackChangeTextInsertion TrackedChange SCXW125721225 BCX0&quot;&gt;&lt;span class=&quot;TrackedChange SCXW125721225 BCX0&quot;&gt;&lt;span class=&quot;TextRun SCXW125721225 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW125721225 BCX0&quot;&gt;(PC&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TrackedChange SCXW125721225 BCX0&quot;&gt;&lt;span class=&quot;TextRun SCXW125721225 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW125721225 BCX0&quot;&gt;A&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TrackChangeTextInsertion TrackedChange SCXW125721225 BCX0&quot;&gt;&lt;span class=&quot;TrackedChange SCXW125721225 BCX0&quot;&gt;&lt;span class=&quot;TextRun SCXW125721225 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW125721225 BCX0&quot;&gt;)&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun SCXW125721225 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW125721225 BCX0&quot;&gt; to reliably serve patients all over Maui in BAYADA’s &lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TrackedChange SCXW125721225 BCX0&quot;&gt;&lt;span class=&quot;TextRun Highlight SCXW125721225 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW125721225 BCX0&quot;&gt;Assistive Care&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun SCXW125721225 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW125721225 BCX0&quot;&gt; Division.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What you’ll do:&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Following a written plan of care by a registered nurse, y&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;ou’ll &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;p&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;rovide&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt; personal care&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt; services&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;, &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;household support, and &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;companion care (homemaker) services &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;to help adults stay safe &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;and&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt; independent at home.&amp;nbsp; &lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;As a BAYADA PCA&lt;span data-contrast=&quot;auto&quot;&gt;,&lt;/span&gt; &lt;span data-contrast=&quot;auto&quot;&gt;you’ll have the opportunity to develop close relationships with your clients while you help them&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;with&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;:&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Activities of daily living: bathing, grooming, toileting, nail care, etc.&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:254}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Household support: light housekeeping, laundry, bed making etc.&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:254}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Meal preparation and feeding&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:254}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Range of motion/exercises&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:254}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Assisting with ambulation (&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Transfers/use of mechanical lifting devices)&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Medication reminders&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:254}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:254}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span class=&quot;TextRun SCXW240643536 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW240643536 BCX0&quot;&gt;What makes you a great candidate:&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW240643536 BCX0&quot; data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt; Previous home health&lt;/span&gt; &lt;span data-contrast=&quot;auto&quot;&gt;care or patient care preferred, but not required. We will train you.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt; A passion for caregiving and a desire to help others&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;.&lt;/span&gt;&lt;/li&gt;
